from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Flood-fill zero regions with 4-connectivity to distinguish bounded holes.
    seen0 = set()
    bounded = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen0:
                continue
            comp = {(r,c)}
            seen0.add((r,c))
            q = deque([(r,c)])
            touches_edge = False
            while q:
                y,x = q.popleft()
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    touches_edge = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx = y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen0:
                        seen0.add((ny,nx)); comp.add((ny,nx)); q.append((ny,nx))
            if not touches_edge:
                bounded.update(comp)
    # Only decorate 1-components that border at least one bounded zero region.
    seen1 = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen1:
                continue
            comp = {(r,c)}
            seen1.add((r,c))
            q = deque([(r,c)])
            while q:
                y,x = q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx = y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny,nx) not in seen1:
                        seen1.add((ny,nx)); comp.add((ny,nx)); q.append((ny,nx))
            inside_adj = set()
            outside_adj = set()
            for y,x in comp:
                # Interior edge is orthogonal; exterior halo uses all eight neighbors.
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx = y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) in bounded:
                        inside_adj.add((ny,nx))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        if dy == dx == 0: continue
                        ny,nx = y+dy,x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in bounded:
                            outside_adj.add((ny,nx))
            if inside_adj:
                # Highlight only the inner edge of a cavity; keep deeper zeros intact.
                for y,x in inside_adj: out[y][x] = 3
                for y,x in outside_adj: out[y][x] = 2
    return out

