from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Flood-fill zero regions with 4-connectivity to distinguish bounded holes.
    seen0 = set()
    bounded = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen0:
                continue
            comp = {(r,c)}
            seen0.add((r,c))
            q = deque([(r,c)])
            touches_edge = False
            while q:
                y,x = q.popleft()
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    touches_edge = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx = y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen0:
                        seen0.add((ny,nx)); comp.add((ny,nx)); q.append((ny,nx))
            if not touches_edge:
                bounded.update(comp)
    # Qualifying 4-connected 1-components enclose a cavity. Color the 8-neighbor
    # inner edge of that cavity and add an 8-neighbor outer halo to the full shape.
    seen1 = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen1:
                continue
            comp = {(r,c)}
            seen1.add((r,c)); q = deque([(r,c)])
            while q:
                y,x=q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) not in seen1:
                        seen1.add((ny,nx)); comp.add((ny,nx)); q.append((ny,nx))
            adjacent_inside=set()
            for y,x in comp:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) in bounded:
                        adjacent_inside.add((ny,nx))
            if not adjacent_inside:
                continue
            for y,x in adjacent_inside: out[y][x]=3
            # Draw a one-cell rectangular halo around the bounding box of the closed component.
            minr=min(y for y,x in comp); maxr=max(y for y,x in comp)
            minc=min(x for y,x in comp); maxc=max(x for y,x in comp)
            for yy in range(max(0,minr-1), min(h-1,maxr+1)+1):
                for xx in range(max(0,minc-1), min(w-1,maxc+1)+1):
                    if yy in (minr-1,maxr+1) or xx in (minc-1,maxc+1):
                        if grid[yy][xx]==0: out[yy][xx]=2
            # Keep inner-edge cells colored 3 where necessary.
            for y,x in adjacent_inside: out[y][x]=3
    return out
