            q=deque([(r,c)]); zeros_seen.add((r,c)); region={(r,c)}; edge=False
            while q:
                y,x=q.popleft()
                if y in (0,h-1) or x in (0,w-1): edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (ny,nx) not in zeros_seen:
                        zeros_seen.add((ny,nx)); region.add((ny,nx)); q.append((ny,nx))
            if not edge: enclosed.update(region)
    # For each connected 1-outline enclosing a cavity, shade cavity edge 3 and
    # its surrounding 8-neighbor exterior cells 2.
    ones_seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in ones_seen: continue
            comp={(r,c)}; ones_seen.add((r,c)); q=deque([(r,c)])
            while q:
                y,x=q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) not in ones_seen:
                        ones_seen.add((ny,nx)); comp.add((ny,nx)); q.append((ny,nx))
            inner=set()
            for y,x in comp:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) in enclosed:
                        inner.add((ny,nx))
            if not inner: continue
            for y,x in comp:
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        if dy==dx==0: continue
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0:
